/**
 * POP CULTURE PACK (thème « pop ») — données pures, AUCUN import (partagé avec convex/cardsCatalog.ts).
 * GÉNÉRÉ par scripts/make-pop.py (ne pas éditer à la main) depuis Tri-etoiles-popculture.xlsx (SPEC-THEME-POP-CULTURE v5).
 * 16480 cartes · 853 sous-thèmes (libellé imprimé en grand sur la carte), regroupés à l'affichage en 7.
 * Numéro = « N° » de l'Excel, sur 17534. Ids « pop-… » figés dans scripts/data/pop-ids.json (ne JAMAIS les changer).
 */
export type PopRarity = 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary' | 'mythic';

export interface PopSub {
  id: string;
  label: string;
  code: string;
  /** groupe d'affichage (mangas & anime, films, séries…) */
  group: string;
}

export interface PopEntry {
  /** identifiant de carte — ne JAMAIS le changer */
  id: string;
  sub: string;
  /** n° de la carte dans tout le thème (1 → 17534) */
  num: number;
  name: string;
  rarity: PopRarity;
  /** fichier dans art/pop ('' = aucune illustration : design typographique) */
  file: string;
  /** 'c' image pleine · 'i' détourée · '' aucune */
  art: '' | 'c' | 'i';
  /** type affiché (« Personnage », « Artiste », « Chanson »…) */
  label: string;
}

export const POP_SIZE = 17534;
export const POP_GROUPS: Record<string, string> = {
  anime: "Mangas & anime",
  films: "Films",
  series: "Séries TV",
  dessins: "Dessins animés",
  musique: "Musique",
  stars: "Acteurs & actrices",
  youtubeurs: "YouTube",
};

